contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value, bytes memory data) public {
        require(address(c).balance >= value);
        uint balBefore = address(c).balance;
        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;
        assert(reverted ? balAfter == balBefore : balAfter == balBefore - value);
    }

    receive() external payable {}
}

